import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [showProfile, setShowProfile] = useState(false);

  const [user, setUser] = useState(
    JSON.parse(localStorage.getItem("user")) || {
      name: "User",
      email: "user@email.com",
    }
  );

  // ✅ HANDLE UPLOAD
  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      const txns = data.transactions || [];

      setTransactions(txns);

      // ✅ smarter detection
      let detected = data.detected_type;
      if (!detected || detected === "unknown") {
        const sample = JSON.stringify(txns).toLowerCase();
        if (sample.includes("gpay") || sample.includes("upi")) detected = "GPay";
        else if (sample.includes("bank")) detected = "Bank";
        else detected = "Statement";
      }

      setType(detected);

      // ✅ SAVE HISTORY
      const history = JSON.parse(localStorage.getItem("history")) || [];

      history.unshift({
        date: new Date().toLocaleString(),
        type: detected,
        count: txns.length,
        data: txns,
      });

      localStorage.setItem("history", JSON.stringify(history));
    } catch (err) {
      console.error(err);
      alert("Upload failed");
    }

    setLoading(false);
  };

  // ✅ HISTORY ACTIONS
  const handleView = (item) => {
    setTransactions(item.data || []);
    setType(item.type || "History");
    setActiveTab("overview");
  };

  const handleDelete = (index) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(index, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("transactions");
  };

  const historyData = JSON.parse(localStorage.getItem("history")) || [];

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* ✅ NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div className="nav-actions">
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "transactions" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("transactions")}
              >
                Transactions
              </span>
            </div>

            {/* ✅ PROFILE ICON */}
            <div
              style={{
                width: "36px",
                height: "36px",
                borderRadius: "50%",
                background: "#2f4b7c",
                color: "white",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
                fontWeight: "bold",
              }}
              onClick={() => setShowProfile(!showProfile)}
            >
              {user.name.charAt(0).toUpperCase()}
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* ✅ PROFILE DROPDOWN */}
        {showProfile && (
          <div
            style={{
              position: "absolute",
              right: "40px",
              top: "80px",
              background: "white",
              padding: "20px",
              borderRadius: "12px",
              boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
              width: "250px",
              zIndex: 10,
            }}
          >
            <h3 style={{ marginBottom: "10px" }}>Profile</h3>

            <input
              value={user.name}
              onChange={(e) =>
                setUser({ ...user, name: e.target.value })
              }
              style={{ width: "100%", marginBottom: "10px" }}
            />

            <input
              value={user.email}
              onChange={(e) =>
                setUser({ ...user, email: e.target.value })
              }
              style={{ width: "100%", marginBottom: "10px" }}
            />

            <button
              onClick={() => {
                localStorage.setItem("user", JSON.stringify(user));
                setShowProfile(false);
              }}
            >
              Save
            </button>
          </div>
        )}

        {/* ✅ HERO */}
        <div className="hero">
          <h1>Personal Expense Intelligence</h1>
          <p>AI-powered financial insights from your statements</p>
        </div>

        {/* ✅ WELCOME */}
        <h2 style={{ marginTop: "20px" }}>
          Welcome, {user.name}
        </h2>

        {/* ✅ KPI */}
        <div className="kpi-grid">
          <div className="kpi-card">
            <h4>Statement Source</h4>
            <p>{type || "Not uploaded"}</p>
          </div>

          <div className="kpi-card">
            <h4>Total Transactions</h4>
            <p>{transactions.length || 0}</p>
          </div>

          <div className="kpi-card">
            <h4>Status</h4>
            <p>{loading ? "Processing..." : transactions.length ? "Processed" : "Waiting"}</p>
          </div>
        </div>

        {/* ✅ OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />
                  <button onClick={handleUpload}>
                    Analyze Statement
                  </button>
                </div>

                {loading && (
                  <p style={{ marginTop: "10px" }}>
                    Processing... Please wait
                  </p>
                )}
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>
                  AI-powered transaction analysis with categorization
                </p>
              </div>
            </div>

            {/* ✅ TABLE */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Amount</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td>{txn.type}</td>
                          <td>{txn.description}</td>
                          <td>₹{txn.amount}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* ✅ TRANSACTIONS TAB = ONLY HISTORY */}
        {activeTab === "transactions" && (
          <div className="card table-card">
            <h3>Upload History</h3>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Source</th>
                    <th>Transactions</th>
                    <th>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {historyData.map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>
                      <td>
                        <button onClick={() => handleView(h)}>
                          View
                        </button>
                        <button
                          onClick={() => handleDelete(i)}
                          style={{ marginLeft: "10px" }}
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
